 * Also validates output redire

import { z } from 'zod/v4';
import { edgeFunctionExample } from '../edge-function.js';
import type { EdgeFunctionsOperations } from '../platform/types.js';
import {
  edgeFunctionSchema,
  edgeFunctionWithBodySchema,
} from '../platform/types.js';
import { injectableTool, type ToolDefs } from './util.js';

type EdgeFunctionToolsOptions = {
  functions: EdgeFunctionsOperations;
  projectId?: string;
  readOnly?: boolean;
};

const listEdgeFunctionsInputSchema = z.object({
  project_id: z.string(),
});

const listEdgeFunctionsOutputSchema = z.object({
  functions: z.array(edgeFunctionSchema),
});

const getEdgeFunctionInputSchema = z.object({
  project_id: z.string(),
  function_slug: z.string(),
});

const getEdgeFunctionOutputSchema = edgeFunctionWithBodySchema;

const deployEdgeFunctionInputSchema = z.object({
  project_id: z.string(),
  name: z.string().describe('The name of the function'),
  entrypoint_path: z
    .string()
    .default('index.ts')
    .describe('The entrypoint of the function'),
  import_map_path: z
    .string()
    .describe('The import map for the function.')
    .optional(),
  verify_jwt: z
    .boolean()
    .default(true)
    .describe(
      "Whether to require a valid JWT in the Authorization header. You SHOULD ALWAYS enable this to ensure authorized access. ONLY disable if the function previously had it disabled OR you've confirmed the function body implements custom authentication (e.g., API keys, webhooks) OR the user explicitly requested it be disabled."
    ),
  files: z
    .array(
      z.object({
        name: z.string(),
        content: z.string(),
      })
    )
    .describe(
      'The files to upload. This should include the entrypoint, deno.json, and any relative dependencies. Include the deno.json and deno.jsonc files to configure the Deno runtime (e.g., compiler options, imports) if they exist.'
    ),
});

const deployEdgeFunctionOutputSchema = edgeFunctionSchema;

export const edgeFunctionToolDefs = {
  list_edge_functions: {
    description: 'Lists all Edge Functions in a Supabase project.',
    parameters: listEdgeFunctionsInputSchema,
    outputSchema: listEdgeFunctionsOutputSchema,
    annotations: {
      title: 'List Edge Functions',
      readOnlyHint: true,
      destructiveHint: false,
      idempotentHint: true,
      openWorldHint: false,
    },
  },
  get_edge_function: {
    description:
      'Retrieves file contents for an Edge Function in a Supabase project.',
    parameters: getEdgeFunctionInputSchema,
    outputSchema: getEdgeFunctionOutputSchema,
    annotations: {
      title: 'Get Edge Function',
      readOnlyHint: true,
      destructiveHint: false,
      idempotentHint: true,
      openWorldHint: false,
    },
  },
  deploy_edge_function: {
    description: `Deploys an Edge Function to a Supabase project. If the function already exists, this will create a new version. Example:\n\n${edgeFunctionExample}`,
    parameters: deployEdgeFunctionInputSchema,
    outputSchema: deployEdgeFunctionOutputSchema,
    annotations: {
      title: 'Deploy Edge Function',
      readOnlyHint: false,
      destructiveHint: true,
      idempotentHint: false,
      openWorldHint: false,
    },
  },
} as const satisfies ToolDefs;

export function getEdgeFunctionTools({
  functions,
  projectId,
  readOnly,
}: EdgeFunctionToolsOptions) {
  const project_id = projectId;

  return {
    list_edge_functions: injectableTool({
      ...edgeFunctionToolDefs.list_edge_functions,
      inject: { project_id },
      execute: async ({ project_id }) => {
        return { functions: await functions.listEdgeFunctions(project_id) };
      },
    }),
    get_edge_function: injectableTool({
      ...edgeFunctionToolDefs.get_edge_function,
      inject: { project_id },
      execute: async ({ project_id, function_slug }) => {
        return await functions.getEdgeFunction(project_id, function_slug);
      },
    }),
    deploy_edge_function: injectableTool({
      ...edgeFunctionToolDefs.deploy_edge_function,
      inject: { project_id },
      execute: async ({
        project_id,
        name,
        entrypoint_path,
        import_map_path,
        verify_jwt,
        files,
      }) => {
        if (readOnly) {
          throw new Error('Cannot deploy an edge function in read-only mode.');
        }

        return await functions.deployEdgeFunction(project_id, {
          name,
          entrypoint_path,
          import_map_path,
          verify_jwt,
          files,
        });
      },
    }),
  };
}

import type { z } from 'zod/v4';
import { CURRENT_FEATURE_GROUPS, type FeatureGroup } from '../types.js';
import { accountToolDefs } from './account-tools.js';
import { branchingToolDefs } from './branching-tools.js';
import { databaseToolDefs } from './database-operation-tools.js';
import { debuggingToolDefs } from './debugging-tools.js';
import { developmentToolDefs } from './development-tools.js';
import { docsToolDefs } from './docs-tools.js';
import { edgeFunctionToolDefs } from './edge-function-tools.js';
import { secretToolDefs } from './secret-tools.js';
import { storageToolDefs } from './storage-tools.js';
import type { ToolDefs } from './util.js';

type DefsToSchemas<T extends ToolDefs> = {
  [K in keyof T]: {
    inputSchema: T[K]['parameters'];
    outputSchema: T[K]['outputSchema'];
    annotations: T[K]['annotations'];
    readOnlyBehavior: T[K] extends {
      readOnlyBehavior: infer R extends 'exclude' | 'adapt';
    }
      ? R
      : undefined;
    hidden: T[K] extends { hidden: infer H extends boolean } ? H : undefined;
  };
};

/** Exported for testing */
export function defsToSchemas<const T extends ToolDefs>(
  defs: T
): DefsToSchemas<T> {
  return Object.fromEntries(
    Object.entries(defs).map(
      ([name, { parameters: inputSchema, description: _, ...rest }]) => [
        name,
        { inputSchema, ...rest },
      ]
    )
  ) as DefsToSchemas<T>;
}

type SchemaEntry = {
  inputSchema: z.ZodObject<any>;
  outputSchema: z.ZodObject<any>;
  annotations: ToolDefs[string]['annotations'];
  readOnlyBehavior?: 'exclude' | 'adapt';
  /** If true, the tool is excluded from `tools/list` but kept in this registry for typed access. */
  hidden?: boolean;
};

/**
 * All Supabase MCP tool schemas (input + output pairs).
 *
 * Pass to AI SDK's `mcpClient.tools()` `schemas` option to get typed tool
 * inputs and outputs:
 * https://ai-sdk.dev/docs/ai-sdk-core/mcp-tools#typed-tool-outputs
 *
 * @example
 * ```typescript
 * import { supabaseMcpToolSchemas } from '@supabase/mcp-server-supabase';
 *
 * const tools = await mcpClient.tools({
 *   schemas: supabaseMcpToolSchemas,
 * });
 * ```
 */
export const supabaseMcpToolSchemas = {
  ...defsToSchemas(accountToolDefs),
  ...defsToSchemas(branchingToolDefs),
  ...defsToSchemas(databaseToolDefs),
  ...defsToSchemas(debuggingToolDefs),
  ...defsToSchemas(developmentToolDefs),
  ...defsToSchemas(docsToolDefs),
  ...defsToSchemas(edgeFunctionToolDefs),
  ...defsToSchemas(secretToolDefs),
  ...defsToSchemas(storageToolDefs),
} satisfies Record<string, SchemaEntry>;

/**
 * Maps each feature group to its tool names.
 * Derived from the per-file tool defs so that adding a tool to a file
 * automatically includes it in the feature group.
 *
 * Used by {@link createToolSchemas} to filter tools by feature.
 */
const FEATURE_TOOL_MAP = {
  docs: Object.keys(docsToolDefs) as readonly (keyof typeof docsToolDefs)[],
  account: Object.keys(
    accountToolDefs
  ) as readonly (keyof typeof accountToolDefs)[],
  database: Object.keys(
    databaseToolDefs
  ) as readonly (keyof typeof databaseToolDefs)[],
  debugging: Object.keys(
    debuggingToolDefs
  ) as readonly (keyof typeof debuggingToolDefs)[],
  development: Object.keys(
    developmentToolDefs
  ) as readonly (keyof typeof developmentToolDefs)[],
  functions: [
    ...Object.keys(edgeFunctionToolDefs),
    ...Object.keys(secretToolDefs),
  ] as readonly (
    | keyof typeof edgeFunctionToolDefs
    | keyof typeof secretToolDefs
  )[],
  branching: Object.keys(
    branchingToolDefs
  ) as readonly (keyof typeof branchingToolDefs)[],
  storage: Object.keys(
    storageToolDefs
  ) as readonly (keyof typeof storageToolDefs)[],
} satisfies Record<
  FeatureGroup,
  readonly (keyof typeof supabaseMcpToolSchemas)[]
>;

/**
 * Schemas with `project_id` omitted from input schemas.
 * Computed dynamically: any tool whose inputSchema has a `project_id`
 * key gets an override with that key omitted.
 *
 * Account tools also appear here but are excluded entirely in
 * project-scoped mode (matching server behavior).
 *
 * Used by {@link createToolSchemas} when `projectScoped` is true.
 */
const PROJECT_SCOPED_OVERRIDES: Record<string, SchemaEntry> =
  Object.fromEntries(
    Object.entries(supabaseMcpToolSchemas)
      .filter(([, { inputSchema }]) => 'project_id' in inputSchema.shape)
      .map(([name, { inputSchema, ...rest }]) => [
        name,
        {
          inputSchema: (inputSchema as z.ZodObject<any>).omit({
            project_id: true,
          }),
          ...rest,
        },
      ])
  );

/**
 * Tools excluded entirely in read-only mode.
 * Derived from tool defs: any tool with `readOnlyHint: false` and no
 * `readOnlyBehavior: 'adapt'` annotation.
 */
export const writeToolSet = new Set(
  Object.entries(supabaseMcpToolSchemas)
    .filter(
      ([, entry]) =>
        entry.annotations.readOnlyHint === false &&
        entry.readOnlyBehavior !== 'adapt'
    )
    .map(([name]) => name)
);

type AllSchemas = typeof supabaseMcpToolSchemas;

/** Tool names whose inputSchema contains `project_id`. */
type ProjectScopedToolName = {
  [K in keyof AllSchemas]: 'project_id' extends keyof z.infer<
    AllSchemas[K]['inputSchema']
  >
    ? K
    : never;
}[keyof AllSchemas];

type ProjectScopedSchemas = {
  [K in ProjectScopedToolName]: {
    inputSchema: AllSchemas[K]['inputSchema'] extends z.ZodObject<infer S>
      ? z.ZodObject<Omit<S, 'project_id'>>
      : never;
    outputSchema: AllSchemas[K]['outputSchema'];
    annotations: AllSchemas[K]['annotations'];
  };
};

type ToolNameForFeature<Feature extends FeatureGroup> =
  (typeof FEATURE_TOOL_MAP)[Feature][number];

type AccountToolName = ToolNameForFeature<'account'>;
type WriteToolName = {
  [K in keyof AllSchemas]: AllSchemas[K]['annotations'] extends {
    readOnlyHint: false;
  }
    ? AllSchemas[K] extends { readOnlyBehavior: 'adapt' }
      ? never
      : K
    : never;
}[keyof AllSchemas];

/**
 * Computes the set of tool names available for a given configuration.
 *
 * - Resolves feature groups to their tool names
 * - Excludes account tools when project-scoped
 * - Excludes write-only tools when read-only
 */
type AvailableToolNames<
  Feature extends FeatureGroup,
  ProjectScoped extends boolean,
  ReadOnly extends boolean,
> = Exclude<
  ToolNameForFeature<Feature>,
  | (ProjectScoped extends true ? AccountToolName : never)
  | (ReadOnly extends true ? WriteToolName : never)
>;

/**
 * Computes the tool schemas for a given configuration.
 *
 * When `ProjectScoped` is `true`, tools with `project_id` use the
 * project-scoped override (with `project_id` omitted from the input
 * schema). All other tools use their original schemas.
 */
type ToolSchemasFor<
  Feature extends FeatureGroup,
  ProjectScoped extends boolean,
  ReadOnly extends boolean,
> = Pick<
  ProjectScoped extends true
    ? Omit<AllSchemas, ProjectScopedToolName> & ProjectScopedSchemas
    : AllSchemas,
  AvailableToolNames<Feature, ProjectScoped, ReadOnly> & keyof AllSchemas
>;

/**
 * Creates a dynamically scoped tool schema map for use with AI SDK's
 * `mcpClient.tools()`.
 *
 * Mirrors the server's dynamic tool behavior:
 * - `features` controls which tool groups are included
 * - `projectScoped` omits `project_id` from input schemas and excludes
 *   account tools (matching server behavior when `projectId` is set)
 * - `readOnly` excludes mutating tools
 *
 * @example
 * ```typescript
 * import { createToolSchemas } from '@supabase/mcp-server-supabase';
 *
 * // Project-scoped with specific features
 * const schemas = createToolSchemas({
 *   features: ['database', 'docs'],
 *   projectScoped: true,
 * });
 *
 * const tools = await mcpClient.tools({ schemas });
 * ```
 */
export function createToolSchemas<
  const Features extends
    readonly FeatureGroup[] = typeof CURRENT_FEATURE_GROUPS,
  const ProjectScoped extends boolean = false,
  const ReadOnly extends boolean = false,
>(options?: {
  features?: Features;
  projectScoped?: ProjectScoped;
  readOnly?: ReadOnly;
}): ToolSchemasFor<Features[number], ProjectScoped, ReadOnly> {
  const enabledFeatures = new Set<string>(
    options?.features ?? CURRENT_FEATURE_GROUPS
  );
  const projectScoped = options?.projectScoped ?? false;
  const readOnly = options?.readOnly ?? false;

  const result: Record<string, SchemaEntry> = {};

  for (const [feature, toolNames] of Object.entries(FEATURE_TOOL_MAP)) {
    if (!enabledFeatures.has(feature)) continue;
    if (projectScoped && feature === 'account') continue;

    for (const toolName of toolNames) {
      if (readOnly && writeToolSet.has(toolName)) continue;

      if (projectScoped && toolName in PROJECT_SCOPED_OVERRIDES) {
        result[toolName] = PROJECT_SCOPED_OVERRIDES[toolName]!;
      } else {
        result[toolName] = supabaseMcpToolSchemas[toolName];
      }
    }
  }

  return result as ToolSchemasFor<Features[number], ProjectScoped, ReadOnly>;
}

import type { ListToolsResult } from '@modelcontextprotocol/sdk/types.js';

import type { ToolKind } from '../utils/contracts.js';
import { OperationError } from '../utils/errors.js';

export type ListedTool = ListToolsResult['tools'][number];

export interface DiscoveredLearnTools {
  docsSearch: ListedTool;
  docsFetch: ListedTool;
  codeSearch: ListedTool;
}

const EXACT_NAMES: Record<ToolKind, string> = {
  docsSearch: 'microsoft_docs_search',
  docsFetch: 'microsoft_docs_fetch',
  codeSearch: 'microsoft_code_sample_search',
};

export function discoverLearnTools(tools: readonly ListedTool[]): DiscoveredLearnTools {
  const docsSearch = pickBestTool('docsSearch', tools);
  const docsFetch = pickBestTool('docsFetch', tools);
  const codeSearch = pickBestTool('codeSearch', tools);

  return {
    docsSearch,
    docsFetch,
    codeSearch,
  };
}

function pickBestTool(kind: ToolKind, tools: readonly ListedTool[]): ListedTool {
  const exactMatch = tools.find((tool) => tool.name === EXACT_NAMES[kind]);
  if (exactMatch) {
    return exactMatch;
  }

  const ranked = tools
    .map((tool) => ({
      tool,
      score: scoreTool(kind, tool),
    }))
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score);

  const bestMatch = ranked[0]?.tool;
  if (bestMatch) {
    return bestMatch;
  }

  throw new OperationError(`Could not map the Learn MCP ${LABELS[kind]} capability from the current tool list.`);
}

function scoreTool(kind: ToolKind, tool: ListedTool): number {
  const haystack = `${tool.name} ${tool.title ?? ''} ${tool.description ?? ''}`.toLowerCase();
  let score = 0;

  switch (kind) {
    case 'docsSearch':
      if (haystack.includes('search')) {
        score += 3;
      }
      if (haystack.includes('docs') || haystack.includes('documentation')) {
        score += 3;
      }
      if (haystack.includes('fetch')) {
        score -= 5;
      }
      if (haystack.includes('code sample') || haystack.includes('snippet')) {
        score -= 5;
      }
      break;
    case 'docsFetch':
      if (haystack.includes('fetch')) {
        score += 4;
      }
      if (haystack.includes('docs') || haystack.includes('documentation')) {
        score += 2;
      }
      if (haystack.includes('search')) {
        score -= 2;
      }
      break;
    case 'codeSearch':
      if (haystack.includes('search')) {
        score += 3;
      }
      if (haystack.includes('code')) {
        score += 3;
      }
      if (haystack.includes('sample')) {
        score += 2;
      }
      if (haystack.includes('fetch')) {
        score -= 5;
      }
      break;
  }

  return score;
}

const LABELS: Record<ToolKind, string> = {
  docsSearch: 'docs search',
  docsFetch: 'docs fetch',
  codeSearch: 'code search',
};

import { describe, expect, it } from 'vitest';

import { discoverLearnTools, type ListedTool } from '../../src/mcp/tool-discovery.js';

function createTool(name: string, description: string): ListedTool {
  return {
    name,
    description,
    inputSchema: {
      type: 'object',
    },
  };
}

describe('discoverLearnTools', () => {
  it('maps the expected Learn tools by exact name', () => {
    const tools = [
      createTool('microsoft_docs_search', 'Search docs.'),
      createTool('microsoft_docs_fetch', 'Fetch docs.'),
      createTool('microsoft_code_sample_search', 'Search code samples.'),
    ];

    const discovered = discoverLearnTools(tools);

    expect(discovered.docsSearch.name).toBe('microsoft_docs_search');
    expect(discovered.docsFetch.name).toBe('microsoft_docs_fetch');
    expect(discovered.codeSearch.name).toBe('microsoft_code_sample_search');
  });

  it('falls back to descriptions when names do not exactly match', () => {
    const tools = [
      createTool('search-docs', 'Search official Microsoft documentation.'),
      createTool('fetch-docs', 'Fetch full documentation page content.'),
      createTool('search-code', 'Search code samples and snippets.'),
    ];

    const discovered = discoverLearnTools(tools);

    expect(discovered.docsSearch.name).toBe('search-docs');
    expect(discovered.docsFetch.name).toBe('fetch-docs');
    expect(discovered.codeSearch.name).toBe('search-code');
  });
});

