const AiSearchResponseSchema = z.object({
  object: z.string(),
  search_query: z.string(),
  data: z.array(
    z.object({
      file_id: z.string(),
      filename: z.string(),
      score: z.number(),
      attributes: z
        .object({
          modified_date: z.number().optional(),
          folder: z.string().optional()
        })
        .catchall(z.any()),
      content: z.array(
        z.object({
          id: z.string(),
          type: z.string(),
          text: z.string()
        })
      )
    })
  ),
  has_more: z.boolean(),
  next_page: z.string().nullable()
